const $ = s => document.querySelector(s);
const icon = (name, group='190-5427') => {const key=group+'-'+name;const [w,h]=assetSizes[key]||[];return `<img class="icon" src="assets/${key}.svg" width="${w}" height="${h}" style="width:${w}px;height:${h}px" alt="">`};
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
