function reviewLabel(n){const last=n%10,lastTwo=n%100;return n+' '+(last===1&&lastTwo!==11?'отзыв':last>=2&&last<=4&&(lastTwo<12||lastTwo>14)?'отзыва':'отзывов')}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2400)}
function updateStatusBackground(){const heroHeight=$('.hero')?.offsetHeight||432;const end=heroHeight-$('#status').offsetHeight;const progress=Math.max(0,Math.min(1,($('#screen').scrollTop-(end-60))/60));$('#status').style.setProperty('--hero-opacity',state.page==='home'?1-progress:0);}
function status(){updateStatusBackground();$('#status').innerHTML=`<span class="time">9:41</span>${icon('imgLocation')}<div class="island">${icon('imgLens')}</div><div class="signals">${icon('imgNetwork')}${icon('imgData')}${icon('imgBattery')}</div>`;}
