function job(i=0){
  const v=vacancies.find(v=>v.id===i)||vacancies[0];
  const favorite=state.favorites.includes(v.id);
  return `<article class="job" data-job="${v.id}">
    <div class="job-title"><button data-action="detail" data-id="${v.id}">${esc(v.title)}</button><button class="icon-button heart ${favorite?'saved':''}" data-action="favorite" data-id="${v.id}" aria-label="${favorite?'Удалить из избранного':'Добавить в избранное'}" aria-pressed="${favorite}">${icon('img1')}</button></div>
    <p class="salary">${esc(v.salary)}</p>
    <div class="badges"><span class="badge">${esc(v.experience)}</span><span class="badge blue">${esc(v.benefit)}</span></div>
    <p class="schedule">${esc(v.schedule)}</p>
    <div class="seller"><div class="seller-info"><div>${icon('imgVerified')}<span>${esc(v.company)}</span></div><div>${icon('imgIcon')}<span>${v.rating}</span><span class="separator-dot" aria-hidden="true"></span><span class="reviews">${reviewLabel(v.reviews)}</span></div><div>${icon('imgElementsMetroLine')}<span>${esc(v.metro)}, ${v.walk} мин.</span>${icon('imgIcon1')}</div></div><div class="seller-logo"></div></div>
    <div class="job-actions"><button data-action="apply" data-id="${v.id}">Откликнуться</button><button data-action="call" data-id="${v.id}">Позвонить</button></div>
  </article>`;
}
function resultIds(){
  const q=state.query.trim().toLowerCase();
  if(!q){const ids=state.browseIds||vacancies.map(v=>v.id);return state.sort?[...ids].reverse():ids;}
  const matches=vacancies.filter(v=>v.title.toLowerCase().includes(q)||q.includes(v.title.toLowerCase()));
  const others=vacancies.filter(v=>!matches.includes(v));
  const ids=[...matches,...others].map(v=>v.id);
  return state.sort?ids.reverse():ids;
}
function hero(){const quick=[['Быстрые деньги','imgIcon4'],['Без работы','imgIcon3'],['Студентам','imgIcon2'],['Подработка','imgIcon1'],['Первый опыт','imgIcon']];return `<header class="hero"><div class="topnav"><button class="icon-button" data-action="back" aria-label="Назад">${icon('imgArrowLeft','header')}</button><div class="role-tabs"><button class="active" data-action="worker">Ищу работу</button><button data-action="employer">Ищу сотрудников</button></div><button class="icon-button" data-action="assistant" aria-label="Помощник">${icon('imgAssistantChats','header')}</button></div><h2>Найдите подходящее</h2><button class="location" data-action="location">${icon('imgLocationAvitoDs','header')}<span>${esc(state.location||'Москва, ул. Пушкина, 33')}</span></button><div class="quick">${quick.map(([label,img])=>`<button data-action="quick" data-value="${label}">${icon(img,'header')}${label}</button>`).join('')}</div><form class="search-form" autocomplete="off"><label class="input-wrap">${icon('imgIcon5','header')}<input name="query" aria-label="Поиск вакансий" placeholder="Например, курьер" autocomplete="off" autocorrect="off" spellcheck="false"></label><button type="button" class="filter-button" data-action="filters" aria-label="Фильтры">${icon('imgFilterAvitoDs','header')}</button></form></header>`}
function popular(){
  const chips=['Для вас','Работа до 17:00','Работа руками','Ночные смены','Работа из дома','Все категории'];
  return `<section class="section popular"><h3>Популярные вакансии</h3><div class="rail popular-chips">${chips.map((c,i)=>`<button class="chip ${state.category===c?'active':''}" data-action="category" data-value="${c}" style="--chip-width:${[79,129,122,122,127,135][i]}px">${c}${i===5?icon('imgArrowRightAvitoDs','190-5525'):''}</button>`).join('')}</div><div class="jobs">${vacancies.map(v=>job(v.id)).join('')}</div></section>`;
}
function collectionCard(c,i){
  const summary=(c.summary||'р-н Аэропорт · Подработки').split(' · ');
  return `<button class="collection-card" data-action="collection" data-id="${i}"><span class="collection-info"><span class="row"><span>${esc(c.name)}</span>${icon('imgIcon1','190-5525')}</span><span class="collection-summary">${summary.map(esc).join('<span class="separator-dot" aria-hidden="true"></span>')}</span></span><span class="count">${c.count??12}<span class="new-badge">+${c.new??3}</span></span></button>`;
}
function viewedCard(v){
  return `<article class="viewed-card"><div class="viewed-title"><button data-action="detail" data-id="${v.id}"><strong>${esc(v.title)}</strong><span>${v.id===3?'100 000–150 000 ₽ за смену':esc(v.salary)}</span></button><button class="icon-button heart ${state.favorites.includes(v.id)?'saved':''}" data-action="favorite" data-id="${v.id}" aria-label="Добавить в избранное" aria-pressed="${state.favorites.includes(v.id)}">${icon('img1')}</button></div><div class="viewed-seller"><div class="viewed-company">${icon('imgVerified','190-5525')}<span>${esc(v.company)}</span></div><div class="viewed-location"><span class="metro-lines">${icon('imgMetro3','190-5525')}${icon('imgMetro2','190-5525')}${icon('imgMetro1','190-5525')}</span><span>${esc(v.metro)},</span><span class="walk">${v.walk} мин.</span>${icon('imgIcon3','190-5525')}</div></div></article>`;
}
function collections(){
  return `<section class="section collections"><h3>Собираем вакансии за вас</h3><p class="subtitle">Складываем их в подборки по вашим условиям</p><div class="rail collection-rail" id="collection-rail">${state.collections.map(collectionCard).join('')}${state.collections.length<1?'':`<button class="collection-card add" id="new-collection" data-action="new"><span class="plus">${icon('imgIcon10','190-5525')}</span><span class="add-label"><strong>Создать подборку</strong><small>Выбрать условия</small></span></button>`}</div></section><section class="section viewed"><h3>Вы смотрели</h3><div class="rail viewed-rail">${[3,15,1,5,2].map(i=>viewedCard(vacancies[i])).join('')}</div></section>`;
}
function search(){return `<div class="search-page"><header class="search-header"><div class="search-top"><button class="icon-button" data-action="back" aria-label="Назад">${icon('imgSize20ProductCommon')}</button><form class="input-wrap search-form" style="margin:0" autocomplete="off"><span>${icon('imgIcon2')}</span><input name="query" aria-label="Поиск вакансий" value="${esc(state.query)}" autocomplete="off" autocorrect="off" spellcheck="false"></form></div><div class="search-location"><button data-action="location">${icon('imgLocationAvitoDs')} ${esc(state.location||'Москва, ул. Пушкина, 33')}</button><button data-action="filters">${icon('imgFilterAvitoDs')} Фильтры</button></div></header><div class="rail search-chips"><button class="chip" data-action="filters">${esc(state.filters[0]||'Все вакансии')} ${icon('imgIcon3')}</button><button class="chip" data-action="filters">Поиск по приоритетам ${icon('imgIcon4')}</button><button class="chip" data-action="frequency">Частота выплат ${icon('imgIcon4')}</button></div><div class="sort-row"><button data-action="sort">${icon('imgSortAvitoDs')} ${state.sort?'Сначала новые':'Сортировка'}</button><button data-action="create">${icon('imgFavoritesOutlineAvitoDs')} Создать подборку</button></div><div class="jobs">${resultIds().map(i=>job(i)).join('')}</div></div>`}
function render(){status();tabs();let html='';if(state.page==='home') html=hero()+(state.collections.length&&!state.hideCollections?collections():'')+popular();else if(state.page==='search') html=search();else if(state.page==='favorites') html=`<div class="empty-state"><h2>Избранное</h2>${state.favorites.length?'':'<p>Сохраняйте вакансии, которые вам понравились</p><button class="primary" data-action="worker">Найти работу</button>'}</div><div class="jobs">${state.favorites.map(i=>job(i)).join('')}</div>`;else html=`<div class="empty-state"><h2>${esc(state.tab)}</h2><p>${state.tab==='Сообщения'?'Здесь появятся ответы работодателей на ваши отклики.':state.tab==='Профиль'?'Ваши подборки сохраняются на этом устройстве.':'Ваши объявления появятся здесь.'}</p><button class="primary" data-action="worker">Найти работу</button></div>`;$('#screen').innerHTML=`<div class="page">${html}</div>`;document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('selected',b.dataset.scene===state.scene));}
function navigate(page,scene=page){state.hideCollections=page==='home'&&scene==='home';state.page=page;state.scene=scene;state.tab=page==='favorites'?'Избранное':'Поиск';render();$('#screen').scrollTop=0;updateStatusBackground();}
function closeSheet(){const overlay=$('#overlay');const sheet=overlay.querySelector('.sheet');if(!sheet)return;sheet.classList.add('closing');overlay.querySelector('.backdrop')?.classList.add('closing');setTimeout(()=>{overlay.innerHTML='';state.sheet=null;$('#screen').inert=false;$('#tabbar').inert=false;state.returnFocus?.focus()},220)}
function openSheet(content,cls=''){state.returnFocus=document.activeElement;$('#screen').inert=true;$('#tabbar').inert=true;$('#overlay').innerHTML=`<div class="overlay"><div class="backdrop" data-action="close"></div><section class="sheet ${cls}" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="handle" aria-label="Потяните вниз, чтобы закрыть"></div>${content}</section></div>`;const focusable=$('#overlay').querySelector('input,button');focusable?.focus({preventScroll:true});const handle=$('.handle');let y;handle.addEventListener('pointerdown',e=>{y=e.clientY;handle.setPointerCapture(e.pointerId)});handle.addEventListener('pointerup',e=>{if(e.clientY-y>45)closeSheet()});}
function create(){state.sheet='create';state.push=true;state.email=false;openSheet(`<h2 id="sheet-title">Создать подборку</h2><p class="sheet-description">Мы сохраним настройки фильтров,<br>и сообщим о новых вакансиях</p><div class="switches">${switchRow('push','Пуш уведомления',true)}${switchRow('email','Письма на почту',false)}</div><form id="create-form" autocomplete="off"><label class="name-field">Название подборки<input name="name" aria-label="Название подборки" placeholder="${esc(state.query||'Например, рядом с домом')}" maxlength="45" autocomplete="off" autocorrect="off" spellcheck="false"></label><p class="filters-label">Фильтры:</p><div class="rail filter-tags" id="filter-tags">${tags()}</div><div class="sheet-footer"><button class="primary" type="submit">Добавить</button></div></form>`,'create-sheet');}
function switchRow(key,label,on){return `<button class="switch-row" type="button" role="switch" aria-checked="${on}" data-action="switch" data-value="${key}">${label}<span class="switch-images ${on?'on':''}">${icon('imgPresetDefaultSizeMDefaultStateDefaultActiveFalse','190-5461')}${icon('imgPresetDefaultSizeMDefaultStateDefaultActiveTrue','190-5461')}</span></button>`}
function tags(){return state.filters.length?state.filters.map((f,i)=>`<button class="chip" style="--tag-width:${({'Продажи':91,'Без опыта':98,'Без резюме':109,'Гибкий график':126})[f]?(({'Продажи':91,'Без опыта':98,'Без резюме':109,'Гибкий график':126})[f]+'px'):'auto'}" type="button" data-action="remove-filter" data-id="${i}" aria-label="Удалить фильтр ${esc(f)}">${icon('imgIcon5','190-5461')}${esc(f)}</button>`).join(''):'<button class="chip" type="button" data-action="filters">Выбрать фильтры</button>'}
function filters(){state.sheet='filters';openSheet(`<h2 id="sheet-title">Фильтры</h2><p class="sheet-description">Выберите условия подходящей работы</p><form id="filters-form" autocomplete="off"><div class="filter-options">${['Продажи','Без опыта','Без резюме','Гибкий график','Подработки','Быстрые выплаты'].map(f=>`<label><input type="checkbox" name="filter" value="${f}" ${state.filters.includes(f)?'checked':''} autocomplete="off" autocorrect="off" spellcheck="false">${f}</label>`).join('')}</div><button class="primary">Показать вакансии</button></form>`);}
function demoCollections(){if(!state.collections.length)state.collections=[{name:'Смены',count:12,new:3},{name:'Стажировки',count:4,new:12}];}
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.matches('.search-form')){state.query=new FormData(e.target).get('query')?.trim()||'';navigate('search')}else if(e.target.id==='create-form'){const name=new FormData(e.target).get('name').trim()||state.query||'Новая подборка';state.collections.unshift({name,query:state.query,count:12,new:3,filters:[...state.filters],push:state.push,email:state.email,summary:state.filters.slice(0,2).join(' · ')});state.freshCollection=true;closeSheet();navigate('home','collections');toast('Подборка «'+name+'» создана');requestAnimationFrame(()=>{$('#collection-rail').scrollLeft=0})}else if(e.target.id==='filters-form'){state.filters=new FormData(e.target).getAll('filter');closeSheet();navigate('search')}else if(e.target.id==='location-form'){state.location=new FormData(e.target).get('location').trim()||'Москва, ул. Пушкина, 33';closeSheet();render();toast('Место поиска обновлено')}else if(e.target.id==='apply-form'){closeSheet();toast('Отклик отправлен работодателю')}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;const id=Number(b.dataset.id);if(a==='close')closeSheet();else if(a==='back'||a==='worker'){closeSheet();navigate('home',state.collections.length?'collections':'home')}else if(a==='quick'){state.filters=b.dataset.value==='Первый опыт'?['Без опыта']:b.dataset.value==='Быстрые деньги'?['Быстрые выплаты']:['Подработки'];state.query=b.dataset.value==='Первый опыт'?'Менеджер по продажам':'Курьер';navigate('search')}else if(a==='category'){state.category=b.dataset.value;state.query=b.dataset.value==='Работа руками'?'Комплектовщик':'Менеджер по продажам';navigate('search')}else if(a==='filters')filters();else if(a==='create')create();else if(a==='new'){state.query='';state.filters=[];state.sort=false;state.browseIds=vacancies.map(v=>v.id);for(let i=state.browseIds.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.browseIds[i],state.browseIds[j]]=[state.browseIds[j],state.browseIds[i]]}closeSheet();navigate('search')}else if(a==='collection'){const c=state.collections[id];state.query=c.query??'Менеджер по продажам';state.filters=[...(c.filters||defaults)];navigate('search')}else if(a==='favorite'){if(state.favorites.includes(id))state.favorites=state.favorites.filter(n=>n!==id);else state.favorites.push(id);if(state.page==='favorites')render();else{b.classList.toggle('saved',state.favorites.includes(id));b.setAttribute('aria-pressed',state.favorites.includes(id));b.setAttribute('aria-label',state.favorites.includes(id)?'Удалить из избранного':'Добавить в избранное')}toast(state.favorites.includes(id)?'Вакансия добавлена в избранное':'Вакансия удалена из избранного')}else if(a==='switch'){state[b.dataset.value]=!state[b.dataset.value];b.setAttribute('aria-checked',state[b.dataset.value]);b.querySelector('.switch-images').classList.toggle('on',state[b.dataset.value])}else if(a==='remove-filter'){state.filters.splice(id,1);$('#filter-tags').innerHTML=tags()}else if(a==='sort'){state.sort=!state.sort;render()}else if(a==='tab'){state.tab=b.dataset.value;if(state.tab==='Поиск')navigate('home',state.collections.length?'collections':'home');else{state.page=state.tab==='Избранное'?'favorites':'other';render();$('#screen').scrollTop=0}}else if(a==='location'){state.sheet='location';openSheet(`<h2 id="sheet-title">Где искать работу?</h2><form id="location-form" autocomplete="off"><input class="sheet-field" aria-label="Адрес поиска" name="location" value="${esc(state.location||'Москва, ул. Пушкина, 33')}" autocomplete="off" autocorrect="off" spellcheck="false"><button class="primary">Сохранить</button></form>`)}else if(a==='detail'){state.sheet='detail';openSheet(`<h2 id="sheet-title">Вакансия</h2><button class="close" data-action="close" aria-label="Закрыть">×</button>${job(id)}<div class="detail-text"><strong>Что предстоит делать</strong><p>Помогать покупателям, консультировать по ассортименту и работать с заказами.</p><br><strong>Условия</strong><p>График 2/2, обучение и стабильные выплаты. Откликнитесь, чтобы связаться с работодателем.</p></div>`,'detail')}else if(a==='apply'){state.sheet='apply';openSheet(`<h2 id="sheet-title">Отклик на вакансию</h2><p class="sheet-description">Работодатель получит ваш отклик и сможет написать вам.</p><form id="apply-form" autocomplete="off"><input class="sheet-field" name="name" aria-label="Ваше имя" placeholder="Ваше имя" required autocomplete="off" autocorrect="off" spellcheck="false"><button class="primary">Отправить отклик</button></form>`)}else if(a==='call'){state.sheet='call';openSheet(`<h2 id="sheet-title">Магазин «Соседи»</h2><p class="detail-text">Телефон работодателя<br><strong>+7 (999) 123-45-67</strong></p><button class="primary" data-action="close">Понятно</button>`)}else if(a==='employer'||a==='assistant'){toast(a==='employer'?'В этом сценарии показан поиск работы':'Опишите вакансию в строке поиска')}else if(a==='frequency'){state.sheet='frequency';openSheet(`<h2 id="sheet-title">Частота выплат</h2><div class="filter-options">${['Ежедневно','Раз в неделю','Два раза в месяц'].map(f=>`<button class="chip" data-action="choose-frequency" data-value="${f}">${f}</button>`).join('')}</div>`)}else if(a==='choose-frequency'){state.filters.push(b.dataset.value);closeSheet();render();toast('Фильтр добавлен')}});
$('#scenarios').addEventListener('click',e=>{const b=e.target.closest('[data-scene]');if(!b)return;$('#overlay').innerHTML='';$('#screen').inert=false;$('#tabbar').inert=false;state.sheet=null;const scene=b.dataset.scene;state.freshCollection=false;if(scene==='home'){navigate('home','home')}else if(scene==='search'||scene==='create'){state.query='Менеджер по продажам';state.filters=[...defaults];navigate('search',scene);if(scene==='create')create()}else{demoCollections();navigate('home',scene);if(scene==='new')requestAnimationFrame(()=>$('#collection-rail').scrollTo({left:273,behavior:'smooth'}))}});
$('#reset').addEventListener('click',()=>{state.collections=[];state.favorites=[];state.freshCollection=false;state.filters=[...defaults];state.query='Менеджер по продажам';$('#overlay').innerHTML='';state.sheet=null;$('#screen').inert=false;$('#tabbar').inert=false;navigate('home');toast('Прототип сброшен')});
document.addEventListener('keydown',e=>{if(!$('#overlay').firstChild)return;if(e.key==='Escape')closeSheet();if(e.key==='Tab'){const nodes=[...$('#overlay').querySelectorAll('button,input,select')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
// Both horizontal carousels support native touch scrolling and mouse dragging.
let railDrag=null;
document.addEventListener('pointerdown',e=>{
  const rail=e.target.closest('.collection-rail,.viewed .rail');
  if(!rail||e.pointerType!=='mouse'||e.button!==0)return;
  railDrag={rail,startX:e.clientX,startScroll:rail.scrollLeft,moved:false,pointerId:e.pointerId};
});
document.addEventListener('pointermove',e=>{
  if(!railDrag||e.pointerId!==railDrag.pointerId)return;
  const dx=e.clientX-railDrag.startX;
  if(Math.abs(dx)>6&&!railDrag.moved){
    railDrag.moved=true;
    railDrag.rail.setPointerCapture(e.pointerId);
    railDrag.rail.classList.add('dragging');
  }
  if(railDrag.moved){e.preventDefault();railDrag.rail.scrollLeft=railDrag.startScroll-dx;}
},{passive:false});
function endRailDrag(){
  if(!railDrag)return;
  const {rail,moved}=railDrag;
  rail.classList.remove('dragging');
  if(moved){rail.dataset.suppressClick='true';setTimeout(()=>delete rail.dataset.suppressClick,0);}
  railDrag=null;
}
document.addEventListener('pointerup',endRailDrag);
document.addEventListener('pointercancel',endRailDrag);
document.addEventListener('click',e=>{
  if(e.target.closest('[data-suppress-click]')){e.preventDefault();e.stopImmediatePropagation();}
},true);
document.addEventListener('dragstart',e=>{if(e.target.closest('.collection-rail,.viewed .rail'))e.preventDefault();});
render();
